save(304,dict(paragraphs=["Haimanti Dutta Ray writes poetry and prose. Her books include In Loving Memory, published in 2015, and The Circle of Life & Other Tales, published in 2018. In her own essay about her father, the painter Shyamal Dutta Ray, intimate recollections of family life sit beside an account of the artistic world she grew up around.","‘Herald in the Chill’, her poem in Kabita Live, welcomes winter with flowers, birds, woollens and cups of tea. Its literary allusions share space with aching bones and the pleasure of ice cream in cold weather. The result is an affectionate, lightly humorous invitation to find renewal in the season’s ordinary comforts."],sources=[source('Haimanti Dutta Ray — Of This & That: Reliving Memories of Shyamal Duttaray','https://thespace.ink/essays/shyamal-dutta-ray-the-painter-as-my-father/',['Author-written recollection of her father; contributor biography names In Loving Memory (Rupali, 2015) and The Circle of Life & Other Tales (Locksley Hall, 2018)'])],identity_match='Full name and debut title/year match captured biography; signed first-person essay and attached contributor bio provide direct corroboration.',poems_read=[dict(id=339,title='HERALD IN THE CHILL',basis='Full original read: winter flowers/birds, sun/woollens, Diwali, tea/fog and humorous physical comforts; Keats and Heathcliff allusions.')],limitations=['No direct publisher product page verified; no speculative book links added.','Opening Keats quotation is not treated as the author’s original line.','No family details beyond the author-published literary context added.'],next_action='Independent author/editor review and optional verified book links.'))
